<script setup>
import { computed, ref } from 'vue'
import { useRouter, RouterLink } from 'vue-router'
import { products, formatIDR } from '../data/products'
import { useCartStore } from '../stores/cart'
const router=useRouter(),cart=useCartStore(),busy=ref(false),error=ref('')
const customer=ref({name:'',email:'',phone:'',address:'',payment:'Transfer bank (simulasi)'})
const rows=computed(()=>cart.items.map(i=>({...i,product:products.find(p=>p.id===i.productId)})).filter(i=>i.product))
function submit(){error.value='';if(!cart.items.length){error.value='Tas kopi masih kosong.';return}busy.value=true;setTimeout(()=>{const order=cart.placeOrder({...customer.value});router.push(`/order/${order.id}`);busy.value=false},350)}
</script>
<template><div class="checkout-page"><div class="breadcrumbs"><RouterLink to="/">Beranda</RouterLink><span>/</span><RouterLink to="/cart">Tas kopi</RouterLink><span>/</span><b>Checkout</b></div><div class="checkout-title"><span class="section-index">LANGKAH TERAKHIR · SIMULASI</span><h1>Ceritakan ke mana<br/><em>kopi ini pergi.</em></h1></div><div class="checkout-layout"><form class="checkout-form" @submit.prevent="submit"><div class="checkout-block"><div class="checkout-block-heading"><span>01</span><div><h2>Info penerima</h2><p>Hanya dipakai untuk membuat contoh pesanan di browser ini.</p></div></div><label>Nama lengkap<input v-model="customer.name" required autocomplete="name" placeholder="Nama kamu"/></label><div class="form-row"><label>Email<input v-model="customer.email" required type="email" autocomplete="email" placeholder="nama@email.com"/></label><label>Nomor WhatsApp<input v-model="customer.phone" required type="tel" autocomplete="tel" placeholder="08xx xxxx xxxx"/></label></div><label>Alamat pengiriman<textarea v-model="customer.address" required autocomplete="street-address" rows="3" placeholder="Jalan, kota, provinsi, kode pos"></textarea></label></div><div class="checkout-block"><div class="checkout-block-heading"><span>02</span><div><h2>Metode pembayaran</h2><p>Pilihan ini hanya visual demo dan tidak memproses pembayaran.</p></div></div><label class="payment-option"><input v-model="customer.payment" type="radio" value="Transfer bank (simulasi)"/><span class="payment-icon">↗</span><span><b>Transfer bank</b><small>Simulasi — tidak ada transfer sungguhan</small></span><i></i></label><label class="payment-option"><input v-model="customer.payment" type="radio" value="QRIS (simulasi)"/><span class="payment-icon">▦</span><span><b>QRIS</b><small>Simulasi — tidak ada pembayaran sungguhan</small></span><i></i></label></div><div v-if="error" class="form-error" role="alert">{{ error }}</div><p class="checkout-demo-warning">Ini hanya frontend demo. Tombol “Buat pesanan” menyimpan contoh pesanan lokal di browser ini.</p><button class="button button-coral checkout-submit" :disabled="busy">{{ busy?'Menyiapkan pesanan…':'Buat pesanan demo' }} <span>↗</span></button></form><aside class="checkout-summary"><span class="section-index">ISI TAS KOPI</span><h2>{{ cart.count }} pilihan</h2><div v-for="item in rows" :key="item.productId+item.size" class="checkout-item"><img :src="item.product.image" :alt="item.product.name"/><div><b>{{ item.product.name }}</b><span>{{ item.qty }} × {{ item.size }} · {{ item.grind }}</span></div><strong>{{ formatIDR(item.product.sizes.find(s=>s.label===item.size).price*item.qty) }}</strong></div><div class="summary-total"><span>Total demo</span><b>{{ formatIDR(cart.subtotal) }}</b></div><RouterLink to="/cart" class="continue-shopping">← Kembali ke tas kopi</RouterLink></aside></div></div></template>
